import React from 'react';
import styled from 'styled-components';

// Định nghĩa các style cho popup và các thành phần bên trong
const PopUpContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopUpForm = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 8px;
  width: 600px;
  max-height: 80%;
  overflow-y: auto;
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background-color: transparent;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #888;

  &:hover {
    color: #000;
  }
`;

const Title = styled.h3`
  text-align: center;
  font-size: 24px;
  margin-bottom: 20px;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
`;

const TableHeader = styled.th`
  background-color: #f4f4f4;
  padding: 10px;
  text-align: left;
  font-weight: bold;
`;

const TableData = styled.td`
  padding: 10px;
  text-align: left;
  border-bottom: 1px solid #ddd;
`;

const TableRow = styled.tr`
  &:hover {
    background-color: #f9f9f9;
  }
`;

const Icon = styled.span`
  cursor: pointer;
  margin-left: 20px;
  color: #007bff;
  font-size: 30px;
  &:hover {
    color: #0056b3;
  }
`;

const ExperimentInfo = ({ showModal, closeModal }) => {
  const experiments = [
    { name: 'Mẫu thí nghiệm 1', fastaFile: 'sample1.fasta' },
    { name: 'Thí nghiệm 2', fastaFile: 'sample2.fasta' },
    { name: 'Thí nghiệm 3', fastaFile: 'sample3.fasta' },
  ];

  if (!showModal) return null; 

  return (
    <PopUpContainer>
      <PopUpForm>
        <CloseButton onClick={closeModal}>×</CloseButton>
        <Title>Thông Tin Thí Nghiệm</Title>
        <Table>
          <thead>
            <tr>
              <TableHeader>STT</TableHeader>
              <TableHeader>Tên Thí Nghiệm</TableHeader>
              <TableHeader>Tên Tệp FASTA</TableHeader>
              <TableHeader>Chi Tiết</TableHeader>
            </tr>
          </thead>
          <tbody>
            {experiments.map((experiment, index) => (
              <TableRow key={index}>
                <TableData>{index + 1}</TableData>
                <TableData>{experiment.name}</TableData>
                <TableData>
                  {experiment.fastaFile}
                  <Icon onClick={() => alert('Tải xuống tệp FASTA')}>⤓</Icon>
                </TableData>
                <TableData>
                  <Icon onClick={() => alert('Xem chi tiết thí nghiệm')}>🔍</Icon>
                </TableData>
              </TableRow>
            ))}
          </tbody>
        </Table>
      </PopUpForm>
    </PopUpContainer>
  );
};

export default ExperimentInfo;
